export const SMP_ITEMS = [{"name":"Miecz Boga","text":"**Miecz Boga** (boska, Skrzynka Bogów, 40 000 $): 16 obrażeń, 1,6 ataku/s • W ręce: Siła I • Co 4. trafienie: piorun, +4 obrażeń • PPM: Gniew Słońca (co 15 s): fala ognia do 7 bloków, 14 obrażeń i podpalenie na 5 s"},{"name":"Włócznia Boga","text":"**Włócznia Boga** (boska, Skrzynka Bogów, 40 000 $): 14 obrażeń, 1,1 ataku/s • W ręce: Szybkość II, zasięg ataku +1 blok • Kucnij + PPM: Szarża (co 11 s): pęd ok. 9 bloków, trafieni dostają 16 obrażeń i Spowolnienie II na 3 s"},{"name":"Młot Boga","text":"**Młot Boga** (boska, Skrzynka Bogów, 40 000 $): 15 obrażeń, 0,8 ataku/s • W ręce: brak obrażeń od upadku i odrzutu • PPM: Uderzenie (co 19 s): wyskok, przy lądowaniu fala w 7 blokach: 16 obrażeń, odrzut i ogłuszenie na 2 s"},{"name":"Łuk Boga","text":"**Łuk Boga** (boska, Skrzynka Bogów, 40 000 $): Strzały ×2,5 obrażeń, lecą prosto i skręcają do najbliższego celu • Nieskończoność • Kucnij + PPM: Deszcz Strzał (co 22 s): 32 strzały po 8 obrażeń spadają tam, gdzie celujesz"},{"name":"Kosa Boga","text":"**Kosa Boga** (boska, Skrzynka Bogów, 40 000 $): 16 obrażeń, 1,2 ataku/s • Każdy cios leczy cię o 10% zadanych obrażeń • Zabójstwo: +4 ❤ i Siła I na 10 s • PPM: Żniwo (co 19 s): kradnie 4 ❤ każdemu w 5 blokach"},{"name":"Trójząb Boga","text":"**Trójząb Boga** (boska, Skrzynka Bogów, 40 000 $): 15 obrażeń wręcz, 17 rzutem, Lojalność III • W ręce: Gracja delfina i oddychanie pod wodą • Trafiony rzut przywołuje piorun (+4) • Kucnij + PPM: Skok Fali (co 5 s), działa też bez deszczu • Fala (co 15 s): tam, gdzie trafi rzut, odrzut i Spowolnienie II w 5 blokach"},{"name":"Hełm Boga","text":"**Hełm Boga** (boska, Skrzynka Bogów, 30 000 $): Pancerz 4, twardość 4 • Kopiesz pod wodą jak na lądzie • Odporność na Ślepotę i Ciemność"},{"name":"Napierśnik Boga","text":"**Napierśnik Boga** (boska, Skrzynka Bogów, 30 000 $): Pancerz 9, twardość 4 • +4 ❤ maksymalnego zdrowia • 15% mniej obrażeń"},{"name":"Spodnie Boga","text":"**Spodnie Boga** (boska, Skrzynka Bogów, 30 000 $): Pancerz 7, twardość 4 • Szybkość II"},{"name":"Buty Boga","text":"**Buty Boga** (boska, Skrzynka Bogów, 30 000 $): Pancerz 4, twardość 4 • Brak obrażeń od upadku, Wyskok II • Podwójny skok: 2× spacja w powietrzu"},{"name":"Hak z Liną","text":"**Hak z Liną** (Rzadka Skrzynka, 3500 $, 200 strzałów): PPM wystrzeliwuje hak do 32 bloków. Trafiony blok: lina się skraca i ciągnie, w powietrzu bujasz się jak na wahadle. Trafiony gracz albo mob leci do ciebie. Kucnięcie albo PPM puszcza linę, po puszczeniu 3 s bez obrażeń od upadku. Odnowienie 3 s."},{"name":"Spadochron","text":"**Spadochron** (Zwykła Skrzynka, 2000 $, 50 otwarć): Działa z ekwipunku. Gdy spadasz z ponad 15 bloków, kucnij: nad głową otwiera się czasza i opadasz powoli. Zwija się po lądowaniu, w wodzie albo po drugim kucnięciu."},{"name":"Kusza z Hakiem","text":"**Kusza z Hakiem** (Rzadka Skrzynka, 4000 $, 465 użyć): Strzał przyciąga cię do miejsca trafienia. Po lądowaniu 3 s bez obrażeń od upadku."},{"name":"Łuk Wielostrzał","text":"**Łuk Wielostrzał** (Rzadka Skrzynka, 4000 $, 384 użycia): Wypuszcza 3 strzały naraz w wachlarzu. Dodatkowych strzał nie da się podnieść."},{"name":"Elytra Klubowa","text":"**Elytra Klubowa** (Za eventy, 15 000 $, 432 użycia): Jasnozielona elytra z oczami Klubisia. Lata jak zwykła."},{"name":"Napierśnik ze Skrzydłami","text":"**Napierśnik ze Skrzydłami** (Zwykła / Rzadka / Legendarna, 2000 / 5000 / 12 000 $): Żelazny, diamentowy albo netherytowy. Pancerz zwykłego napierśnika, a na plecach skrzydła-peleryna: latasz jak na elytrze."},{"name":"Mały Plecak","text":"**Mały Plecak** (Zwykła Skrzynka, 1000 $): PPM otwiera schowek na 9 miejsc. Rzeczy są zapisane w plecaku. Największy plecak z ekwipunku widać na twoich plecach (inni widzą, ty nie)."},{"name":"Średni Plecak","text":"**Średni Plecak** (Rzadka Skrzynka, Crafting, 1400 $): Schowek na 18 miejsc. Robisz go z małego plecaka i rzeczy w środku zostają."},{"name":"Duży Plecak","text":"**Duży Plecak** (Legendarna Skrzynka, Crafting, 3000 $): Schowek na 27 miejsc. Robisz go ze średniego plecaka i rzeczy w środku zostają. Plecaka nie da się włożyć do plecaka."},{"name":"Łza Boga","text":"**Łza Boga** (legendarna, Zwykła, Rzadka, Legendarna, 7000 $): Składnik Skrzynki Bogów. Najrzadsza nagroda Zwykłej Skrzynki."},{"name":"Czekan","text":"**Czekan** (Crafting, 33 $, 400 bloków w górę): Trzymaj w ręce (głównej albo drugiej) przy pełnym bloku. W: wspinanie 3 bloki/s (drabina 2,35). A/D: w bok po ścianie. Bez klawiszy: zsuwanie 1 blok/s. Kucnięcie: wiszenie. Spacja: odbicie od ściany. S: puszczenie. Na szczycie ściany podciągasz się na krawędź. Na ścianie upadek liczy się od nowa. Męczy jak sprint. Nie działa na barierach ani na cudzych działkach."},{"name":"Papier prezentowy","text":"**Papier prezentowy** (Crafting (3 szt.), 2 $): 4 wzory: czerwony ze złotą wstążką, zielony z Klubisiem, niebieski w gwiazdki, złoty. PPM otwiera okno pakowania: do 9 stosów (bez prezentów oraz shulkerów i plecaków z zawartością), adresat albo prezent dla każdego, dedykacja do 60 znaków. ZAPAKUJ zużywa jeden arkusz, zamknięcie okna oddaje przedmioty."},{"name":"Zatruty Miecz","text":"**Zatruty Miecz**: 30 / 30 / 45% szansy na Truciznę I / I / II na 3 / 5 / 5 s."},{"name":"Lodowy Miecz","text":"**Lodowy Miecz**: 30 / 30 / 45% szansy na Spowolnienie I / I / II na 3 s."},{"name":"Wampirzy Miecz","text":"**Wampirzy Miecz**: Każdy cios leczy cię o 10 / 15 / 20% zadanych obrażeń."},{"name":"Mroczny Miecz","text":"**Mroczny Miecz**: 30 / 30 / 45% szansy na Wither I na 3 / 4 / 5 s."},{"name":"Miecz Prędkości","text":"**Miecz Prędkości**: W ręce: Szybkość I / II / III."},{"name":"Miecz Skoku","text":"**Miecz Skoku**: W ręce: Wyskok I / II / III."},{"name":"Miecz Regeneracji","text":"**Miecz Regeneracji**: W ręce: Regeneracja I / I / II."},{"name":"Siekiera Drwala","text":"**Siekiera Drwala**: Ścina całe drzewo uderzeniem w pień. Kucnij, żeby ściąć jeden blok."},{"name":"Siekiera Berserka","text":"**Siekiera Berserka**: +5% obrażeń za każde brakujące ❤, najwyżej +50%."},{"name":"Krwawa Siekiera","text":"**Krwawa Siekiera**: 30 / 30 / 45% szansy na krwawienie: 1 / 1,5 / 2 obrażeń co sekundę przez 3 s."},{"name":"Siekiera Łamacza","text":"**Siekiera Łamacza**: Im więcej pancerza ma trafiony, tym mocniej: do +15 / 20 / 25% obrażeń."},{"name":"Kilof Górnika","text":"**Kilof Górnika**: Kopie 3×3. Kucnij, żeby kopać jeden blok."},{"name":"Kilof Przetapiania","text":"**Kilof Przetapiania**: Rudy, bruk i piasek wypadają od razu przetopione."},{"name":"Kilof Szczęścia","text":"**Kilof Szczęścia**: 10 / 15 / 20% szansy na podwójny drop z rud."},{"name":"Kilof Pośpiechu","text":"**Kilof Pośpiechu**: W ręce: Haste I / II / II."},{"name":"Kilof Magnesu","text":"**Kilof Magnesu**: Wykopany drop leci prosto do ekwipunku."},{"name":"Kolczasta Tarcza","text":"**Kolczasta Tarcza**: Napastnik dostaje 2 / 3 / 4 obrażeń."},{"name":"Odpychająca Tarcza","text":"**Odpychająca Tarcza**: Napastnik odlatuje z siłą 1,2 / 1,5 / 1,8, najwyżej raz na 15 s."},{"name":"Lodowa Tarcza","text":"**Lodowa Tarcza**: Napastnik dostaje Spowolnienie I / I / II na 2 s."},{"name":"Zbroja Odporności","text":"**Zbroja Odporności**: −3 / 4 / 5% obrażeń na część, razem najwyżej 50%."},{"name":"Zbroja Lawy","text":"**Zbroja Lawy**: Palisz się krócej o 10 / 15 / 20% na część, razem najwyżej 80%."},{"name":"Zbroja Kolców","text":"**Zbroja Kolców**: Odbija 3 / 4 / 5% obrażeń wręcz do napastnika na część, razem najwyżej 50%. Hełm 3D z kolcami."},{"name":"Zbroja Zdrowia","text":"**Zbroja Zdrowia**: +0,5 / 1 / 1 ❤ na część, razem najwyżej +4 ❤."},{"name":"Zbroja Lekkości","text":"**Zbroja Lekkości**: +3 / 4 / 5% szybkości na część, razem najwyżej 30%. Hełm ze skrzydełkami, skrzydła na plecach."},{"name":"Zbroja Piór","text":"**Zbroja Piór**: −15 / 20 / 25% obrażeń od upadku na część, razem najwyżej 80%. Hełm 3D z pióropuszem."},{"name":"Kwarc Mleczny","text":"**Kwarc Mleczny** (pospolita): +5% doświadczenia na część."},{"name":"Piryt","text":"**Piryt** (pospolita): +5% kasy za sprzedaż w Club'o'Macie na część."},{"name":"Agat","text":"**Agat** (pospolita): −5% obrażeń od upadku na część."},{"name":"Jaspis","text":"**Jaspis** (pospolita): −5% obrażeń od ognia i lawy na część."},{"name":"Hematyt","text":"**Hematyt** (pospolita): +5% odporności na odrzut na część."},{"name":"Malachit","text":"**Malachit** (rzadka): +10% leczenia na część."},{"name":"Akwamaryn","text":"**Akwamaryn** (rzadka): +5 s oddechu pod wodą na część."},{"name":"Granat","text":"**Granat** (rzadka): +5% obrażeń wręcz na część."},{"name":"Cytryn","text":"**Cytryn** (rzadka): +5% szybkości na część."},{"name":"Szafir","text":"**Szafir** (epicka): 5% szansy na część, że cios (wręcz albo pocisk) cię nie zrani."},{"name":"Rubin","text":"**Rubin** (epicka): 10% szansy na część, że atakujący zapłonie na 3 s."},{"name":"Tanzanit","text":"**Tanzanit** (epicka): Widzisz w ciemności, 8% szansy na część na Ciemność u trafionego gracza na 2 s."},{"name":"Opal Ognisty","text":"**Opal Ognisty** (legendarna): −25% obrażeń od ognia i lawy na część, atakujący wręcz płonie 3 s."},{"name":"Czarny Diament","text":"**Czarny Diament** (legendarna): +1 pancerza i 10% szansy na odbicie strzały na część."},{"name":"Klubit","text":"**Klubit** (mityczna): +1 ❤ na część. Raz na 10 min śmiertelny cios zostawia ci 1 ❤."},{"name":"Totem Płomieni","text":"**Totem Płomieni**: Siła I na 10 s, odporność na ogień na 30 s, podpala wszystkich do 5 bloków na 5 s."},{"name":"Totem Mrozu","text":"**Totem Mrozu**: Siła I i Odporność I na 10 s, Spowolnienie III na 4 s dla wszystkich do 5 bloków."},{"name":"Totem Wichru","text":"**Totem Wichru**: Szybkość II i Wyskok II na 10 s, odrzuca wszystkich do 5 bloków."},{"name":"Totem Krwi","text":"**Totem Krwi**: Pełne zdrowie zamiast pół serca, Siła II na 8 s, Regeneracja II na 10 s."},{"name":"Totem Ziemi","text":"**Totem Ziemi**: Absorpcja IV i Siła I na 10 s, Odporność II na 5 s."},{"name":"Karta Siły","text":"**Karta Siły** (Wszystkie skrzynki, 800 $): Król kier. PPM: +10% Siły."},{"name":"Karta Ochrony","text":"**Karta Ochrony** (Wszystkie skrzynki, 800 $): Dama pik. PPM: +10% Ochrony."},{"name":"Karta Szybkości","text":"**Karta Szybkości** (Wszystkie skrzynki, 800 $): Walet karo. PPM: +10% Szybkości."},{"name":"Karta Haste","text":"**Karta Haste** (Wszystkie skrzynki, 800 $): As trefl. PPM: +10% Haste. Haste przyspiesza też ataki."},{"name":"Karta Jokera","text":"**Karta Jokera** (legendarna, Rzadka, Legendarna, Bogów, Crafting, 4000 $): Karta Odrodzenia. Rzuć ją (Q) na grób gracza albo kliknij nią grób: gracz wraca ze skillami po 100%. Potrzebna też do craftingu skrzynek i Terminala."},{"name":"Klubik","text":"**Klubik** (mityczna, Skrzynka Bogów, 60 000 $): Obrażenia i pancerz 200%, Szybkość I, Regeneracja I, odporność na ogień, brak obrażeń od upadku. Poniżej 3 ❤: Odporność IV i Absorpcja II na 4 s (co 5 min)."},{"name":"Smok","text":"**Smok** (legendarna, Legendarna, Bogów, 15 000 $): Obrażenia ×1,4, każdy cios podpala na 3 s. Raz na minutę oddech smoka pod trafionym graczem."},{"name":"Feniks","text":"**Feniks** (legendarna, Legendarna, Bogów, 15 000 $): Raz na 10 min zamiast śmierci wstajesz z 4 ❤ i podpalasz wszystkich dookoła."},{"name":"Yeti","text":"**Yeti** (legendarna, Legendarna, Bogów, 15 000 $): Pancerz ×1,3, nie zamarzasz w sypkim śniegu, 30% szansy na Spowolnienie II na 3 s przy ciosie."},{"name":"Golem","text":"**Golem** (epicka, Rzadka Skrzynka, 5000 $): Odporność I, +1 ❤, o połowę mniejszy odrzut."},{"name":"Robot","text":"**Robot** (epicka, Rzadka Skrzynka, 5000 $): Haste II, Szybkość I."},{"name":"Pszczółka","text":"**Pszczółka** (epicka, Rzadka Skrzynka, 5000 $): Regeneracja I, 30% szansy na Truciznę przy ciosie."},{"name":"Sowa","text":"**Sowa** (epicka, Rzadka Skrzynka, 5000 $): Nocne widzenie. Co 30 s podświetla graczy w 24 blokach na 3 s (wszyscy ich widzą)."},{"name":"Szlamik","text":"**Szlamik** (epicka, Rzadka Skrzynka, 5000 $): Co 30 s twój cios odrzuca ×1,5 dalej. Ty dostajesz o połowę mniejszy odrzut."},{"name":"Duszek","text":"**Duszek** (epicka, Rzadka Skrzynka, 5000 $): Poniżej 4 ❤: Niewidzialność i Szybkość II na 5 s, a moby tracą cel (co 5 min)."},{"name":"Lis","text":"**Lis** (rzadka, Zwykła Skrzynka, 2000 $): Szybkość II, Wyskok I."},{"name":"Żółw","text":"**Żółw** (rzadka, Zwykła Skrzynka, 2000 $): Oddychanie pod wodą, szybkie pływanie, pancerz ×1,2."},{"name":"Żabka","text":"**Żabka** (rzadka, Zwykła Skrzynka, 2000 $): Wyskok II, brak obrażeń od upadku."},{"name":"Kotek","text":"**Kotek** (rzadka, Zwykła Skrzynka, 2000 $): Creepery cię nie atakują. Przy creeperze (8 bloków) Szybkość II."},{"name":"Grzybek","text":"**Grzybek** (rzadka, Zwykła Skrzynka, 2000 $): Co 20 s oddaje 1 punkt głodu."},{"name":"Płotka","text":"**Płotka** (pospolita, 0,1–0,6 kg, 2 $): Rzeki."},{"name":"Karaś","text":"**Karaś** (pospolita, 0,2–1,5 kg, 3 $): Bagna, równiny, lasy, łąki, sawanna, tajga."},{"name":"Okoń","text":"**Okoń** (pospolita, 0,1–1,2 kg, 3 $): Wszędzie."},{"name":"Śledź","text":"**Śledź** (pospolita, 0,1–0,5 kg, 4 $): Ocean."},{"name":"Makrela","text":"**Makrela** (pospolita, 0,2–1,0 kg, 5 $): Ciepły ocean."},{"name":"Szczupak","text":"**Szczupak** (rzadka, 1–12 kg, 30 $): Rzeki, bagna."},{"name":"Pstrąg tęczowy","text":"**Pstrąg tęczowy** (rzadka, 0,5–4 kg, 25 $): Tajga, zimne i śnieżne biomy, góry."},{"name":"Węgorz","text":"**Węgorz** (rzadka, 0,5–3 kg, 40 $): Bagna, tylko nocą."},{"name":"Flądra","text":"**Flądra** (rzadka, 0,3–2,5 kg, 15 $): Ocean, plaże."},{"name":"Sum Olbrzym","text":"**Sum Olbrzym** (epicka, 10–60 kg, 200 $): Rzeki, tylko nocą."},{"name":"Żabnica Głębinowa","text":"**Żabnica Głębinowa** (epicka, 2–15 kg, 150 $): Głęboki ocean, tylko nocą."},{"name":"Lodowa Ryba","text":"**Lodowa Ryba** (epicka, 0,5–4 kg, 120 $): Zamarznięte i śnieżne biomy."},{"name":"Złota Karpica","text":"**Złota Karpica** (legendarna, 2–20 kg, 600 $): Tylko w deszczu, w zwykłym świecie."},{"name":"Ryba Pustki","text":"**Ryba Pustki** (legendarna, 1–8 kg, 800 $): Woda w Endzie."},{"name":"Klubiśka","text":"**Klubiśka** (mityczna, 0,5–3 kg, 2000 $): Wszędzie."},{"name":"Kwarc Mleczny","text":"**Kwarc Mleczny** (pospolita, 2 $): Wszędzie."},{"name":"Piryt","text":"**Piryt** (pospolita, 3 $): Wszędzie."},{"name":"Agat","text":"**Agat** (pospolita, 3 $): Wszędzie."},{"name":"Jaspis","text":"**Jaspis** (pospolita, 4 $): Badlands, pustynia."},{"name":"Hematyt","text":"**Hematyt** (pospolita, 5 $): Tylko łupek głębinowy."},{"name":"Malachit","text":"**Malachit** (rzadka, 25 $): Bujne jaskinie."},{"name":"Akwamaryn","text":"**Akwamaryn** (rzadka, 25 $): Zimne biomy, góry, łąki."},{"name":"Granat","text":"**Granat** (rzadka, 20 $): Poniżej y 30."},{"name":"Cytryn","text":"**Cytryn** (rzadka, 30 $): Pustynia, sawanna, badlands."},{"name":"Szafir","text":"**Szafir** (epicka, 150 $): Tylko łupek głębinowy."},{"name":"Rubin","text":"**Rubin** (epicka, 200 $): Łupek głębinowy przy lawie."},{"name":"Tanzanit","text":"**Tanzanit** (epicka, 120 $): Deep Dark."},{"name":"Opal Ognisty","text":"**Opal Ognisty** (legendarna, 600 $): Łupek głębinowy przy lawie."},{"name":"Czarny Diament","text":"**Czarny Diament** (legendarna, 800 $): Poniżej y −40."},{"name":"Klubit","text":"**Klubit** (mityczna, 2500 $): Wszędzie."},{"name":"Zwykła Skrzynka","text":"**Zwykła Skrzynka** (Zabójstwa graczy, 500 $): Mały Plecak, Spadochron, Żelazny Napierśnik ze Skrzydłami, Łza Boga (najrzadsza), rzadkie pety, karty skilli, żelazne przedmioty z dodatkami, totemy."},{"name":"Rzadka Skrzynka","text":"**Rzadka Skrzynka** (Zabójstwa graczy, Crafting, 3000 $): Średni Plecak, Kusza z Hakiem, Łuk Wielostrzał, Hak z Liną, Diamentowy Napierśnik ze Skrzydłami, Łza Boga, epickie pety, karty (też Joker), diamentowe przedmioty z dodatkami, totemy."},{"name":"Legendarna Skrzynka","text":"**Legendarna Skrzynka** (Tylko crafting, 15 000 $): Duży Plecak, Netherytowy Napierśnik ze Skrzydłami, Łza Boga, Smok, Feniks, Yeti, karty, netherytowe przedmioty z dodatkami, totemy."},{"name":"Skrzynka Bogów","text":"**Skrzynka Bogów** (boska, Tylko crafting, 30 000 $): Bronie Boga, Zbroja Boga, Smok, Feniks, Yeti, Klubik, karty."},{"name":"Skrzynka pocztowa","text":"**Skrzynka pocztowa** (Crafting, 60 $): PPM: odbierz pocztę albo wyślij paczkę dowolnemu graczowi, także offline. Paczka wychodzi, gdy zamkniesz okno. Odbiorca może mieć najwyżej 54 stosy."},{"name":"Terminal","text":"**Terminal** (Crafting, 4500 $): Twój sklep. SPRZEDAŻ: gracze kupują od ciebie, a kasa przychodzi także offline. ODKUP: ty skupujesz, kwota jest blokowana z góry. Jeden sklep na gracza, terminali może być wiele. Wygląd: tablet, stragan albo mini automat. Terminal na wykupionej działce pokazuje sklep na /rynek. Od każdej sprzedaży 5% podatku."},{"name":"Wystawa","text":"**Wystawa** (Crafting, 15 $): Postument. PPM i wybierasz ofertę ze swojego sklepu: nad postumentem lewituje przedmiot z ceną, a inni kupują go jednym kliknięciem. Najwyżej 3 na gracza."},{"name":"Słupek tyrolki","text":"**Słupek tyrolki** (Crafting (2 szt.), 10 $): Ze smyczą w ręce kliknij PPM jeden słupek, potem drugi: rozpinasz linę do 64 bloków, do 4 lin na słupek. PPM na słupek bez smyczy = zjazd po linie w stronę, w którą patrzysz (w dół do 20 bloków/s, płasko i pod górę 6). Kucnięcie = zeskok, potem 3 s bez obrażeń od upadku."},{"name":"Trofeum","text":"**Trofeum** (Od admina): Statuetka z głową gracza i napisem, np. za wygrany turniej. Po rozbiciu wraca to samo trofeum."},{"name":"Club'o'Mat","text":"**Club'o'Mat** (Na spawnie): Skup przedmiotów: rzuć przedmiot (Q) w automat i dostajesz jego wartość. PPM otwiera wycenę: wkładasz przedmiot i widzisz kwotę."},{"name":"Club'o'Repair","text":"**Club'o'Repair** (Na spawnie): Naprawa przedmiotów specjalnych za kasę: 30% wartości × zużycie."},{"name":"Club'o'Upgrader","text":"**Club'o'Upgrader** (Na spawnie): Ulepszanie przedmiotów za kasę: 3 ścieżki po 5 poziomów (sekcja niżej)."},{"name":"Tablica Wanted","text":"**Tablica Wanted** (Na spawnie): 3 najwyższe zlecenia na głowy graczy, z twarzami i kwotami. Świeci w ciemności."},{"name":"Prezent","text":"**Prezent** (Z papieru prezentowego): Pudełko z ukrytą zawartością, w opisie od kogo, dla kogo i dedykacja. PPM w powietrze: otwierasz w ręce. PPM na blok: stawiasz; PPM na postawiony: 3 podskoki, wieczko odlatuje, konfetti i przedmioty wyskakują. Otwiera tylko adresat, a gdy go nie ma, każdy. Zabrać postawiony może nadawca, adresat i ten, kto go postawił. Nadawca dostaje wiadomość o otwarciu. Można wysłać pocztą. Club'o'Mat nie skupuje prezentów."},{"name":"Plik dolarów","text":"**Plik dolarów** (/wyplac <kwota>): Kasa z portfela jako przedmiot: można ją dać, zgubić albo ukraść. PPM na plik wpłaca go z powrotem. Plik 100 $ jest składnikiem Terminala."}];
export const SMP_GROUPS = [{"name":"Bronie Boga","text":"**Bronie Boga**: Najmocniejsze bronie na serwerze. Tylko ze Skrzynki Bogów. Każda ma 5000 użyć, a umiejętność zużywa 3 punkty. Zużyta do zera jest „Zepsuta”: nie znika, ale nie działa, dopóki jej nie naprawisz w Club'o'Repair."},{"name":"Zbroja Boga","text":"**Zbroja Boga**: Biały netheryt. Tylko ze Skrzynki Bogów, 5000 użyć na część. Każda część ma odporność na odrzut 0,15."},{"name":"Gadżety i specjalne","text":"**Gadżety i specjalne**: Przedmioty specjalne psują się, ale przy zerze nie znikają: są „Zepsute”, dopóki nie naprawisz ich w Club'o'Repair."},{"name":"Miecze z dodatkami","text":"**Miecze z dodatkami**: Każdy dodatek jest żelazny, diamentowy i netherytowy (wartości [ż / d / n]). Żelazne wypadają ze Zwykłej Skrzynki, diamentowe z Rzadkiej, netherytowe z Legendarnej. Ceny: 600 / 2000 / 4000 $. Psują się jak zwykłe, kowadło i Mending je naprawiają. Efekty przy ciosie działają tylko przy pełnym pasku ataku."},{"name":"Siekiery, kilofy i tarcze","text":"**Siekiery, kilofy i tarcze**: Tak samo jak miecze: trzy bazy [ż / d / n], te same skrzynki i ceny, psują się jak zwykłe. Tarcza działa, gdy zablokuje cios wręcz."},{"name":"Zbroje z dodatkami","text":"**Zbroje z dodatkami**: Każda założona część działa sama, kilka części się sumuje (bez bonusu za komplet). Wartości na jedną część [ż / d / n]. Źródła, ceny i naprawa jak przy mieczach."},{"name":"Zbroja z oprawą i kamienie","text":"**Zbroja z oprawą i kamienie**: Żelazna, diamentowa albo netherytowa zbroja z gniazdem na minerał (crafting: część zbroi + 2 sztabki złota). Weź minerał na kursor i kliknij nim w część zbroi w ekwipunku: kamień siada w oprawie, a stary przepada. Efekty części się sumują. Siła zależy od czystości minerału: 100% = pełna wartość z tabeli, 50% = połowa. Psuje się jak zwykła zbroja."},{"name":"Totemy","text":"**Totemy**: Działają jak totem nieśmiertelności w ręce, a gdy cię uratują, dają dodatkowe efekty. Wypadają ze Zwykłej, Rzadkiej i Legendarnej Skrzynki. Cena: 3000 $."},{"name":"Karty i skille","text":"**Karty i skille**: Każdy gracz ma 4 skille: Siła, Ochrona, Szybkość i Haste. Startują od 100%, najwyżej 250%. Procenty widać na pasku nad ekwipunkiem."},{"name":"Pety","text":"**Pety**: Ze skrzynki wypada kupon. PPM na kupon odblokowuje peta na zawsze, a /pet otwiera menu, w którym go przywołujesz. Umiejętności działają, dopóki pet lata przy tobie."},{"name":"Ryby","text":"**Ryby**: Złowiony dorsz, łosoś, ryba tropikalna albo rozdymka z szansą 50% zamienia się w rybę Club SMP. Śmieci i skarby z wędki zostają zwykłe. Rzadkość: pospolita 70%, rzadka 20%, epicka 8%, legendarna 1,8%, mityczna 0,2%. Morze Szczęścia daje więcej rzadkich ryb."},{"name":"Minerały","text":"**Minerały**: Wypadają przy kopaniu naturalnego kamienia (1%) i łupku głębinowego (1,5%). Każdy poziom Szczęścia na kilofie dodaje 0,3%, a Kilof Górnika liczy każdy blok z 3×3. Rzadkości jak u ryb."},{"name":"Skrzynki","text":"**Skrzynki**: Postaw skrzynkę, żeby wylosować nagrodę. LPM w powietrze ze skrzynką w ręce pokazuje, co jest w środku."},{"name":"Bloki","text":"**Bloki**: Bloki Club SMP obracają się przodem do stawiającego i działają wszędzie, także na działkach."},{"name":"Pieniądze","text":"**Pieniądze**: Każdy ma portfel i bank. Bank nie płaci odsetek, ale kasa w nim jest bezpieczna."},{"name":"Zużycie i ulepszanie","text":"**Zużycie i ulepszanie**: Przedmioty specjalne (Bronie i Zbroja Boga, Hak, Spadochron, Kusza, Łuk Wielostrzał, Elytra Klubowa, napierśniki ze skrzydłami) przy zerze są „Zepsute”: nie znikają, ale nie działają. Naprawia je tylko Club'o'Repair. Kowadło, kamień szlifierski i Mending ich nie naprawiają. Przedmioty z dodatkami i zbroja z oprawą psują się jak zwykłe. Nie psują się: plecaki, totemy, karty, pety, skrzynki, ryby i minerały."}];
